    91→const TestimonialCard = ({ testimonial }: { testimonial: Testimonial }) => (
    92→  <div className="bg-neo-bg border-2 border-neo-border p-6 md:p-8 h-full transition-all duration-300 hover:-translate-y-1 hover:shadow-[6px_6px_0px_0px_var(--neo-accent)]">
    93→    {/* Quote & Stars */}
