   124→const TestimonialsCarousel = ({
   125→  testimonials,
   126→  locale,
   127→}: {
   128→  testimonials: Testimonial[];
   129→  locale: string;
   130→}) => {
   131→  const [currentIndex, setCurrentIndex] = useState(0);
   132→  const [isPaused, setIsPaused] = useState(false);
   133→
   134→  // Duplicate array for infinite loop effect
   135→  const extendedTestimonials = [...testimonials, ...testimonials, ...testimonials];
   136→  const offset = testimonials.length; // Start from middle set
   137→
   138→  const nextSlide = useCallback(() => {
   139→    setCurrentIndex((prev) => (prev + 1) % testimonials.length);
   140→  }, [testimonials.length]);
   141→
   142→  const prevSlide = useCallback(() => {
   143→    setCurrentIndex((prev) => (prev - 1 + testimonials.length) % testimonials.length);
   144→  }, [testimonials.length]);
   145→
   146→  // Auto-scroll lent (6 secondes)
   147→  useEffect(() => {
   148→    if (isPaused) return;
   149→    const interval = setInterval(nextSlide, 6000);
   150→    return () => clearInterval(interval);
   151→  }, [isPaused, nextSlide]);
   152→
   153→  // Calculate the translateX percentage
   154→  // Each card is ~33.33% width on desktop with gap
   155→  const getTranslateX = () => {
   156→    // We show 3 cards at a time, so each step moves by 1 card width (~33.33%)
   157→    return `calc(-${(currentIndex + offset) * 33.333}% - ${(currentIndex + offset) * 8}px)`;
   158→  };
   159→
   160→  return (
   161→    <section
   162→      className="py-24 bg-neo-surface overflow-hidden"
   163→      onMouseEnter={() => setIsPaused(true)}
   164→      onMouseLeave={() => setIsPaused(false)}
   165→    >
   166→      <div className="container mx-auto px-4 md:px-6">
   167→        {/* Header */}
   168→        <div className="flex flex-col md:flex-row md:items-end md:justify-between mb-12">
   169→          <div>
   170→            <div className="font-mono font-bold text-neo-accent mb-4 flex items-center gap-2">
   171→              <span className="bg-neo-text text-neo-accent px-2 py-1">05</span>
   172→              <span className="text-neo-text/60">
   173→                // {locale === "fr" ? "AVIS CLIENTS" : "CLIENT REVIEWS"}
   174→              </span>
   175→            </div>
   176→            <h2 className="text-4xl md:text-5xl font-black uppercase tracking-tight text-neo-text">
   177→              {locale === "fr" ? "Témoignages" : "Testimonials"}
   178→            </h2>
   179→            <p className="font-mono text-sm text-neo-text/60 mt-2 max-w-md">
   180→              {locale === "fr"
   181→                ? "Retours de mes collaborateurs sur SoundBetter"
   182→                : "Feedback from my collaborators on SoundBetter"}
   183→            </p>
   184→          </div>
   185→
   186→          {/* Navigation Arrows */}
   187→          <div className="flex items-center gap-3 mt-6 md:mt-0">
   188→            <button
   189→              onClick={prevSlide}
   190→              className="w-12 h-12 bg-neo-text text-neo-text-inverse flex items-center justify-center border-2 border-neo-border hover:bg-neo-accent hover:text-neo-text transition-colors"
   191→              aria-label="Previous"
   192→            >
   193→              <ChevronLeft className="w-6 h-6" />
   194→            </button>
   195→            <button
   196→              onClick={nextSlide}
   197→              className="w-12 h-12 bg-neo-text text-neo-text-inverse flex items-center justify-center border-2 border-neo-border hover:bg-neo-accent hover:text-neo-text transition-colors"
   198→              aria-label="Next"
   199→            >
   200→              <ChevronRight className="w-6 h-6" />
   201→            </button>
   202→          </div>
   203→        </div>
   204→
   205→        {/* Carousel - Sliding container */}
   206→        <div className="relative overflow-hidden py-2 -my-2">
   207→          <motion.div
   208→            className="flex gap-6 pt-2"
   209→            animate={{ x: getTranslateX() }}
   210→            transition={{ duration: 0.6, ease: [0.25, 0.4, 0.25, 1] }}
   211→          >
   212→            {extendedTestimonials.map((testimonial, index) => (
   213→              <div
   214→                key={`${testimonial.id}-${index}`}
   215→                className="w-full md:w-[calc(50%-12px)] lg:w-[calc(33.333%-16px)] flex-shrink-0"
   216→              >
   217→                <TestimonialCard testimonial={testimonial} />
   218→              </div>
   219→            ))}
   220→          </motion.div>
   221→        </div>
   222→
   223→        {/* Progress Dots */}
   224→        <div className="flex justify-center gap-3 mt-8">
   225→          {testimonials.map((_, index) => (
   226→            <button
   227→              key={index}
   228→              onClick={() => setCurrentIndex(index)}
   229→              className={`h-3 border-2 border-neo-border transition-all duration-300 ${
   230→                index === currentIndex ? "w-10 bg-neo-accent" : "w-3 bg-neo-bg hover:bg-neo-text/20"
   231→              }`}
   232→              aria-label={`Go to slide ${index + 1}`}
   233→            />
   234→          ))}
   235→        </div>
   236→
   237→        {/* CTA SoundBetter - Orange accent button */}
   238→        <div className="text-center mt-12">
   239→          <a
   240→            href="https://soundbetter.com/profiles/402365-lo%C3%AFc-ghanem--voyager1"
   241→            target="_blank"
   242→            rel="noopener noreferrer"
   243→            className="inline-flex items-center gap-3 bg-neo-accent text-neo-text-inverse px-8 py-4 font-bold uppercase tracking-wide border-2 border-neo-border hover:bg-neo-text hover:text-neo-accent transition-colors shadow-[4px_4px_0px_0px_var(--neo-text)] hover:shadow-none hover:translate-x-1 hover:translate-y-1"
   244→          >
   245→            <Star className="w-5 h-5" />
   246→            {locale === "fr"
   247→              ? "Voir tous les avis sur SoundBetter"
   248→              : "View All Reviews on SoundBetter"}
   249→            <ExternalLink className="w-5 h-5" />
   250→          </a>
   251→        </div>
   252→      </div>
   253→    </section>
   254→  );
   255→};
