/* ============================================
   IMPORTS
   ============================================ */
@import "./tokens.css";
@import "./admin-tokens.css";

@tailwind base;
@tailwind components;
@tailwind utilities;

/* ============================================
   BASE LAYER - Typography, Reset & Scrollbar
   ============================================ */
@layer base {
  /* Reset */
  * {
    box-sizing: border-box;
    padding: 0;
    margin: 0;
  }

  html,
  body {
    max-width: 100vw;
    overflow-x: hidden;
  }

  body {
    color: var(--foreground);
    background: var(--background);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  a {
    text-decoration: none;
  }

  /* Links inherit color only if no explicit color class is set */
  a:where(:not([class*="text-"])) {
    color: inherit;
  }

  /* Typography */
  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    @apply font-display font-bold;
    color: var(--text-primary);
  }

  h1 {
    @apply text-5xl md:text-6xl lg:text-7xl leading-tight;
  }

  h2 {
    @apply text-4xl md:text-5xl leading-tight;
  }

  h3 {
    @apply text-3xl md:text-4xl leading-snug;
  }

  h4 {
    @apply text-2xl md:text-3xl leading-snug;
  }

  h5 {
    @apply text-xl md:text-2xl leading-normal;
  }

  h6 {
    @apply text-lg md:text-xl leading-normal;
  }

  p {
    @apply text-base leading-relaxed;
    color: var(--text-secondary);
  }

  /* Scrollbar Styling */
  ::-webkit-scrollbar {
    @apply w-2;
  }

  ::-webkit-scrollbar-track {
    background: var(--surface);
  }

  ::-webkit-scrollbar-thumb {
    @apply rounded-full;
    background: var(--neo-accent);
  }

  ::-webkit-scrollbar-thumb:hover {
    background: var(--neo-accent);

