      "fullDescription": "My music production services encompass every stage of the process. With a deep understanding of music theory, a keen ear for detail, and proficiency in the latest production software, I am equipped to bring your musical ideas to fruition. Whether you need help with arranging, recording, mixing, or mastering, I provide a comprehensive solution tailored to your project's needs.",
      "details": {
        "intro": "I handle the **complete production** of your musical projects, from conception to final realization. My expertise covers all aspects of modern production.",
        "approach": "With a studio equipped with the latest technologies and in-depth knowledge of multiple musical genres, I transform your ideas into professional productions ready for distribution.",
        "services": [
          "Multi-genre production (Metal, Hip-Hop, Electronic, Ambient)",
          "Programming and sound design",
          "Recording and artistic direction",
          "Mastering for all formats"
        ]
      }
    },
    "arranging": {
      "title": "Arranging",
      "description": "Orchestral and instrumental arrangements to enhance your compositions.",
      "largeTitle": "Arranging: Enhancing Your Compositions",
      "fullDescription": "My arranging skills will add depth and complexity to your music. With my extensive knowledge of orchestration and harmony, I will craft arrangements that bring out the best in your compositions. Whether you have a fully formed composition or a simple melody, I can transform it into a rich, fully realized piece of music.",
      "details": {
        "intro": "**Arranging** is the art of structuring and dressing a composition to reveal its full potential. I work on orchestration, harmony, and sonic texture to create rich and coherent arrangements.",
        "approach": "From symphonic orchestration to modern electronic arrangements, I master a wide range of techniques to bring your musical ideas to life.",
        "services": [
          "Symphonic and modern orchestration",
          "Arrangements for acoustic ensembles",
          "Reharmonization and adaptation",
          "Creation of hybrid textures"
        ]
      }
    },
    "vocalProducer": {
      "title": "Vocal Producer",
      "description": "Vocal direction and production for exceptional performances.",
      "largeTitle": "Vocal Production: Elevating Your Vocal Performances",
      "fullDescription": "As a vocal producer, I specialize in bringing out the best in a singer's performance. I assist singers with their vocal melodies, ensuring they deliver the best possible performance for their recordings. I offer specialized services such as correcting, mixing, and arranging vocals. I am skilled at pitch correction, vocal comping, and I can enhance performances using effects and processing tools. My job is to make the vocal shine, ensuring it fits perfectly within the mix and contributes effectively to the song's overall feel and message.",
      "details": {
        "intro": "As a **vocal producer**, I guide artists to capture the best vocal performances. My role is to extract the emotion and power from each voice.",
        "approach": "From pre-production to recording, I accompany singers through their creative process, providing precise and caring artistic direction.",
        "services": [
          "Vocal artistic direction",
          "Pre-session preparation and coaching",
          "Vocal recording and editing",
          "Voice processing and production"
        ]
      }
    },
    "mixing": {
      "title": "Mixing",
      "description": "Professional mixing for balanced and punchy sound.",
      "largeTitle": "Mixing: Polishing Your Music to Perfection",
      "fullDescription": "Mixing is a critical step in the music production process, and one that I excel in. I will balance the elements of your track, ensuring that no instrument or voice is too loud or too soft. My mixing techniques will also add depth and dimension to your music, creating a soundscape that is rich and engaging.",
      "details": {
        "intro": "**Mixing** is the crucial step that transforms raw tracks into a cohesive and professional production. I balance, equalize, and shape each element to create an impactful mix.",
        "approach": "With an analytical and creative approach, I optimize the clarity, depth, and dynamics of your tracks so they sound perfect on all playback systems.",
        "services": [
          "Stereo and surround mixing",
          "Dynamic and frequency processing",
          "Spatialization and creative effects",
          "Optimization for streaming and broadcast"
        ]
      }
    },
    "mastering": {
      "title": "Mastering",
      "description": "High-quality mastering for optimal finalization of your productions.",
      "largeTitle": "Mastering: The Final Touch for Your Music",
      "fullDescription": "Mastering is the final step in the music production process, and it's one that I take very seriously. I will ensure your tracks are ready for distribution, optimizing them for all playback systems. My mastering services will give your music the final polish it needs, ensuring it sounds professional and stands up against other commercial releases.",
      "details": {
        "intro": "**Mastering** is the final touch that gives your music its professional shine. I prepare your tracks for distribution by optimizing the level, spectral balance, and consistency between tracks.",
        "approach": "My approach to mastering ensures your music sounds optimal on all listening systems, from headphones to hi-fi systems, while respecting industry standards.",
        "services": [
          "Mastering for all formats (streaming, CD, vinyl)",
          "Spectral and dynamic optimization",
          "Consistency between album tracks",
          "Preparation for digital distribution"
        ]
      }
    }
